import {CATALOG,BY_ID,LIMITS,CATEGORIES,QUESTIONS} from './catalog.js';
import {fresh,copy,totals,availability,freeHosts,freeSupports,addUnit,removeUnit,assignUnit,submit,revise,submissionErrors,parseDocument} from './engine.js';
const KEY='flottenatelier.v1';
const $=s=>document.querySelector(s);
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
let state=fresh(),history=[],category='Alle',query='',selected='frigate',tab='fleet',snapshot=null,storageOK=true,toastTimer;
try{const saved=localStorage.getItem(KEY);if(saved)state=parseDocument(JSON.parse(saved));}catch(e){storageOK=false;setTimeout(()=>notice('Gespeicherten Entwurf nicht geladen. '+e.message+' Eine vorhandene Speicherung wird erst nach einer eigenen Änderung ersetzt.',true),200);}
const current=()=>snapshot===null?state.draft:state.submissions[snapshot];
const locked=()=>snapshot!==null||state.draft.status==='submitted';
const count=(type,units=current().units)=>units.filter(u=>u.type===type).length;
const label=(unit,units=current().units)=>BY_ID[unit.type].name+' '+(units.filter(u=>u.type===unit.type).findIndex(u=>u.id===unit.id)+1);
function notice(message,error=false){const t=$('#toast');clearTimeout(toastTimer);t.textContent=message;t.className='show'+(error?' error':'');toastTimer=setTimeout(()=>t.className='',error?9000:4200);}
function save(){try{localStorage.setItem(KEY,JSON.stringify(state));storageOK=true;}catch{storageOK=false;notice('Speichern im Browser nicht möglich. Bitte sichert euren Entwurf mit „Exportieren“.',true);}const status=$('#save-status');if(status)status.textContent=storageOK?'Auf diesem Gerät gespeichert':'Bitte als Datei sichern';}
function commit(next,undo=true){if(undo){history.push(copy(state.draft));if(history.length>40)history.shift();}state=next;save();render();}
function act(action){try{action();}catch(e){notice(e.message,true);}}
function art(shape,cls=''){const paths={
 frigate:'M15 65H218L196 83H46Z M62 65V49H123L137 57H164V65 M91 49V35H117V49 M105 35V14 M90 23H123 M149 61V43H163V61 M41 65V58H68 M180 65V56H198 M54 83L48 89H202',
 corvette:'M28 65H214L192 82H53Z M71 65V47H116L134 60H168V65 M96 47V25 M85 35H110 M165 60V53H186 M48 82L42 88H199',
 submarine:'M35 65Q25 51 48 48H186Q216 49 218 66Q214 79 188 79H48Q26 77 35 65Z M103 48V31H129V48 M114 31V18 M121 31V23 M35 56L20 48V77L35 69 M52 85H199',
 supply:'M19 64H217L201 83H43Z M49 64V31H87V64 M56 40H78 M56 48H78 M102 64V49H124V64 M137 64V43H161V64 M175 64V50H195V64 M66 31V18 M105 49V30H173V43 M102 37H173 M44 88H204',
 carrier:'M16 60H224L202 80H45Z M8 55H228V60H16 M139 55V34H170V55 M150 34V23H160V34 M155 23V10 M141 20H176 M45 49H98 M61 43L72 38L86 43 M177 49H205 M46 86H206',
 plane:'M112 11L120 16L126 47L213 68V76L126 65L122 79L153 89V94L117 88L80 94V89L111 79L107 65L20 76V68L107 47L110 17Z',
 helicopter:'M90 51Q96 39 127 41L153 58V69H85L59 59H20V52H86 M119 41V26 M66 25H180 M41 17L76 25 M98 76V83H155 M133 69V83 M19 52V36 M9 42H32 M132 46L143 57H125V44',
 drone:'M100 44H134V65H100Z M100 44L74 30 M134 44L161 30 M100 65L75 80 M134 65L161 80 M55 29H93 M143 29H180 M56 81H94 M143 81H181 M108 54H126',
 missile:'M65 79L160 24L184 19L173 40L78 95Z M87 67L71 49L103 58 M126 70L139 87L139 62 M57 92L36 100 M57 82L24 94',
 network:'M117 22V52 M52 77L117 52L183 77 M117 52V90 M43 64H61V82H43Z M174 64H192V82H174Z M108 9H126V27H108Z M108 85H126V103H108Z M101 43H133V61H101Z',
 base:'M37 83V43L79 20L122 43V83 M49 83V52H110V83 M134 83V51H202V83 M148 51V32H171V51 M160 32V12 M149 18H177 M25 89H213',
 marines:'M56 44A13 13 0 1 0 56 18A13 13 0 1 0 56 44 M35 88V62Q56 40 78 62V88 M117 39A15 15 0 1 0 117 9A15 15 0 1 0 117 39 M88 93V59Q117 35 146 59V93 M178 44A13 13 0 1 0 178 18A13 13 0 1 0 178 44 M157 88V62Q178 40 200 62V88'
};return `<svg class="silhouette ${cls}" viewBox="0 0 240 112" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><path d="${paths[shape]||paths.frigate}"/></svg>`;}
function costChips(c){return `<div class="cost-chips"><span title="Aufbaukapital">A <b>${c.cost.build}</b></span><span title="Jährlicher Betrieb">B <b>${c.cost.operation}</b></span><span title="Personal">P <b>${c.cost.personnel}</b></span></div>`;}
function render(){const scrolls=['#catalog-list','#dropzone','.detail-scroll'].map(selector=>[selector,$(selector)?.scrollTop||0]);const active=document.activeElement;const focus=active?.dataset.action?{action:active.dataset.action,type:active.dataset.type,unit:active.dataset.unit}:null;const d=current(),t=totals(d.units),platforms=d.units.filter(u=>['Kampfschiffe','Unterstützung'].includes(BY_ID[u.type].category)||['dock','amphibiousCarrier'].includes(u.type)).length;
 $('#app').innerHTML=`<header class="topbar"><a class="brand" href="./" aria-label="Flottenatelier Startseite"><span class="brand-mark">${art('frigate')}</span><span>Flotten<span class="brand-light">atelier</span><small>STRATEGISCHE MARINEPLANUNG</small></span></a><div class="group-field"><label for="group-name">EURE GRUPPE</label><input id="group-name" maxlength="100" placeholder="Gruppennamen eingeben" value="${esc(d.name)}" ${locked()?'disabled':''}></div><div class="top-actions"><button data-action="help" class="quiet">Spielregeln <span class="help-mark">?</span></button><button data-action="files" class="quiet">Datei <span>⌄</span></button><span id="save-status" class="save-status">${storageOK?'Auf diesem Gerät gespeichert':'Bitte als Datei sichern'}</span></div></header>
 <section class="resource-strip" aria-label="Verfügbare Ressourcen">${Object.entries(LIMITS).map(([k,max],i)=>{const used=t[k],over=used>max;return `<div class="resource ${over?'over':''}"><div class="resource-symbol">${['◇','↻','♧'][i]}</div><div class="resource-body"><div class="resource-title">${['Aufbaukapital','Jährlicher Betrieb','Personal'][i]}<span>${over?'Grenze überschritten':`${max-used} frei`}</span></div><div class="resource-value">${used}<span> / ${max} <small>Punkte</small></span></div><div class="resource-track" role="meter" aria-label="${['Aufbaukapital','Jährlicher Betrieb','Personal'][i]} verbraucht" aria-valuemin="0" aria-valuemax="${max}" aria-valuenow="${Math.min(used,max)}" aria-valuetext="${used} von ${max} Punkten"><i style="width:${Math.min(100,used/max*100)}%"></i></div></div></div>`;}).join('')}</section>
 <main id="workspace"><aside class="catalog-panel" aria-label="Bausteinkatalog"><div class="panel-heading"><div><span class="eyebrow">01 / BAUSTEINE</span><h2>Was braucht eure Marine?</h2></div><span class="counter">24</span></div><div class="search"><span>⌕</span><input id="search" type="search" placeholder="Baustein suchen …" value="${esc(query)}" aria-label="Katalog durchsuchen"></div><div class="filter-row"><select id="category" aria-label="Kategorie">${CATEGORIES.map(c=>`<option ${c===category?'selected':''}>${c}</option>`).join('')}</select><span id="results-count"></span></div><div id="catalog-list"></div><div class="catalog-foot">A Aufbau &nbsp; B Betrieb &nbsp; P Personal</div></aside>
 <section class="planning-panel"><div class="planning-head"><div><span class="eyebrow">02 / EUER ENTWURF</span><h1>${snapshot!==null?'Abgabe ansehen':state.draft.status==='submitted'?'Entwurf abgegeben':'Eine Marine. Eure Entscheidungen.'}</h1></div><span class="phase-badge">${d.iteration===1?'Erstentwurf':'Überarbeitung '+(d.iteration-1)}</span></div><div class="workspace-tabs"><div role="tablist" aria-label="Ansicht"><button role="tab" aria-selected="${tab==='fleet'}" data-action="tab" data-tab="fleet" class="${tab==='fleet'?'active':''}">Flottenentwurf <span>${platforms}</span></button><button role="tab" aria-selected="${tab==='rationale'}" data-action="tab" data-tab="rationale" class="${tab==='rationale'?'active':''}">Begründung <span>${QUESTIONS.filter(([k])=>d.rationale[k].trim()).length}/4</span></button></div><button class="undo" data-action="undo" ${!history.length||locked()?'disabled':''} title="Letzte Änderung zurücknehmen">↶ <span>Rückgängig</span></button></div>
 ${snapshot!==null?`<div class="version-banner">Gesicherte Abgabe vom ${new Date(d.submittedAt).toLocaleString('de-DE')}<button data-action="current">Zum aktuellen Stand →</button></div>`:state.draft.status==='submitted'?'<div class="version-banner">Euer Ausgangsentwurf ist gesichert.<button data-action="revise">Überarbeitung beginnen →</button></div>':''}
 <div class="workspace-content" id="dropzone">${tab==='fleet'?fleetView(d):rationaleView(d)}</div><footer class="planning-footer"><span class="foot-note">${locked()?'Gesicherter Stand · schreibgeschützt':'Freier Entwurf · keine automatische Bewertung'}</span><button data-action="summary" class="primary">${locked()?'Abgabe ansehen':'Entwurf abschließen'} <span>→</span></button></footer></section>
 <aside class="details-panel" id="details-panel" aria-label="Kartendetails"></aside></main>
 <footer class="page-footer"><span>AUFTRAG → ENTWURF → DISKUSSION</span><span>Fiktive Spielpunkte. Reale Entscheidungen.</span><button data-action="versions">${state.submissions.length} gespeicherte Abgabe${state.submissions.length===1?'':'n'} ↗</button></footer>`;
 renderCatalog();renderDetails();bindInputs();for(const [selector,y]of scrolls)if($(selector))$(selector).scrollTop=y;if(focus){const replacement=[...document.querySelectorAll('[data-action]')].find(el=>el.dataset.action===focus.action&&el.dataset.type===focus.type&&el.dataset.unit===focus.unit&&!el.disabled);replacement?.focus({preventScroll:true});}}
function renderCatalog(){const cards=CATALOG.filter(c=>(category==='Alle'||c.category===category)&&(c.name+' '+c.description).toLocaleLowerCase('de').includes(query.toLocaleLowerCase('de')));$('#results-count').textContent=cards.length+' Karten';$('#catalog-list').innerHTML=cards.map(c=>{const why=availability(current().units,c.id);return `<article class="catalog-card ${selected===c.id?'selected':''}" draggable="${!locked()&&!why}" data-type="${c.id}"><button class="card-select" data-action="select" data-type="${c.id}" aria-label="Details: ${esc(c.name)}"><div class="card-visual">${art(c.shape)}${count(c.id)?`<span class="in-fleet">${count(c.id)} in Flotte</span>`:''}</div><h3>${esc(c.name)}</h3><p>${esc(c.unit)}</p></button><div class="card-bottom">${costChips(c)}<button class="add-card" data-action="quickadd" data-type="${c.id}" aria-label="${esc(c.name)} hinzufügen" ${locked()||why?'disabled':''} title="${esc(why||'Hinzufügen')}">+</button></div>${why&&!locked()?`<button class="requirement" data-action="select" data-type="${c.id}">${esc(why)} <span>↗</span></button>`:''}</article>`;}).join('')||'<p class="no-results">Keine passenden Bausteine. Versucht einen anderen Suchbegriff.</p>';}
function fleetView(d){if(!d.units.length)return `<div class="empty-fleet"><div class="empty-chart"><div class="orbit orbit-one"></div><div class="orbit orbit-two"></div><div class="crosshair"></div>${art('frigate')}</div><span class="eyebrow">DIE GRÜNE WIESE IST BLAU.</span><h2>Euer Auftrag.<br>Eure Flotte.</h2><p>Wählt den ersten Baustein aus dem Katalog.<br>Jede Entscheidung verändert euren Spielraum.</p><div class="empty-instruction"><span>+</span> Hinzufügen oder hierher ziehen</div></div>`;
 const groups=[['Kampfschiffe','Kampfschiffe'],['Unterstützung','Versorgung & Aufklärung'],['Luftfahrzeuge','Marineflieger'],['Unbemannte Systeme','Unbemannte Systeme'],['Ausstattung','Ausstattung & Strukturen'],['Amphibische Kräfte','Amphibische Kräfte']];
 return `<div class="fleet-groups">${groups.map(([key,title])=>{const cards=CATALOG.filter(c=>c.category===key&&d.units.some(u=>u.type===c.id));return cards.length?`<section class="fleet-section"><div class="fleet-section-title"><h2>${title}</h2><span>${cards.reduce((sum,c)=>sum+count(c.id),0)} Bausteine</span></div><div class="fleet-grid">${cards.map(c=>{const qty=count(c.id),why=availability(d.units,c.id),attached=d.units.filter(u=>u.type===c.id&&u.parentId).length;return `<article class="fleet-stack ${selected===c.id?'selected':''}"><button data-action="select" data-type="${c.id}" class="fleet-stack-main"><span class="stack-number">${String(qty).padStart(2,'0')}<small>×</small></span>${art(c.shape)}<h3>${esc(c.name)}</h3><p>${attached?attached+' zugeordnet':esc(c.unit)}</p></button><div class="stack-controls"><span>${qty*c.cost.build} A · ${qty*c.cost.operation} B · ${qty*c.cost.personnel} P</span><div><button data-action="decrease" data-type="${c.id}" aria-label="Eine Einheit ${esc(c.name)} entfernen" ${locked()?'disabled':''}>−</button><button data-action="quickadd" data-type="${c.id}" aria-label="Eine Einheit ${esc(c.name)} hinzufügen" ${locked()||why?'disabled':''}>+</button></div></div></article>`;}).join('')}</div></section>`:'';}).join('')}<div class="fleet-drop-hint">Weitere Bausteine aus dem Katalog hierher ziehen</div></div>`;}
function rationaleView(d){return `<div class="rationale-view"><span class="eyebrow">EURE ENTSCHEIDUNGEN SICHTBAR MACHEN</span><h2>Was steckt hinter eurer Flotte?</h2><p>Haltet eure Überlegungen für die gemeinsame Diskussion fest. Es gibt keine Musterlösung.</p>${QUESTIONS.map(([key,text],i)=>`<label class="question-label" for="rationale-${key}"><span>0${i+1}</span>${text}</label><textarea id="rationale-${key}" data-rationale="${key}" maxlength="5000" rows="4" placeholder="Eure Überlegungen …" ${locked()?'disabled':''}>${esc(d.rationale[key])}</textarea>`).join('')}</div>`;}
function unitOption(u,currentId){return `<option value="${esc(u.id)}" ${u.id===currentId?'selected':''}>${esc(label(u))}</option>`;}
function renderDetails(){const c=BY_ID[selected],units=current().units,why=availability(units,c.id),hosts=c.hosts?freeHosts(units,c.id):[],supports=c.support?freeSupports(units,c.id):[];
 $('#details-panel').innerHTML=`<div class="panel-heading"><span class="eyebrow">03 / IM DETAIL</span><span class="detail-id">${String(CATALOG.indexOf(c)+1).padStart(2,'0')} / 24</span></div><div class="detail-scroll"><div class="detail-visual">${art(c.shape)}<span>${esc(c.category)}</span></div><h2>${esc(c.name)}</h2><p class="detail-unit">${esc(c.unit)}</p><p class="detail-description">${esc(c.description)}</p><div class="detail-costs">${Object.entries(c.cost).map(([k,v],i)=>`<div><b>${v}</b><span>${['Aufbau','Betrieb','Personal'][i]}</span></div>`).join('')}</div><div class="properties"><h3>Beiträge</h3>${c.strengths.map(s=>`<p><span class="dot"></span>${esc(s)}</p>`).join('')}<h3>Grenzen & Abwägungen</h3>${c.limits.map(s=>`<p><span class="dash">—</span>${esc(s)}</p>`).join('')}</div>${(c.requires?.length||c.hosts||c.support)?`<div class="requirements-detail"><h3>Voraussetzungen</h3>${(c.requires||[]).map(id=>`<button data-action="select" data-type="${id}"><span>${units.some(u=>u.type===id)?'✓':'○'}</span>${esc(BY_ID[id].name)} ↗</button>`).join('')}${c.hosts?`<p>${c.optionalHost?'Optional zuordnen: ':'Plattform: '}${c.hosts.map(id=>BY_ID[id].name).join(' / ')}</p>`:''}${c.support?`<p>Ein eigenes Paket ${BY_ID[c.support].name}</p>`:''}</div>`:''}
 ${!locked()&&c.hosts?`<label class="select-label" for="add-host">Plattform für neues Paket</label><select id="add-host">${c.optionalHost?'<option value="">Landgestützt vorhalten</option>':''}${hosts.map(u=>unitOption(u)).join('')}${!hosts.length&&!c.optionalHost?'<option value="">Keine freie Plattform</option>':''}</select>`:''}
 ${!locked()&&c.support?`<label class="select-label" for="add-support">Logistik für neues Paket</label><select id="add-support">${supports.map(u=>unitOption(u)).join('')}${!supports.length?'<option value="">Kein freies Logistikpaket</option>':''}</select>`:''}
 <button class="detail-add primary" data-action="detailadd" data-type="${c.id}" ${locked()||why?'disabled':''}>${c.unique&&count(c.id)?'Bereits in eurer Flotte':'+ Zur Flotte hinzufügen'}</button>${why&&!locked()?`<p class="detail-reason">${esc(why)}</p>`:''}
 ${count(c.id)?`<div class="instance-section"><h3>In eurer Flotte <span>${count(c.id)}</span></h3>${units.filter(u=>u.type===c.id).map(u=>instanceView(u,c,units)).join('')}</div>`:''}</div>`;}
function instanceView(u,c,units){const children=units.filter(p=>p.parentId===u.id||p.supportId===u.id);return `<div class="instance"><div class="instance-head"><strong>${esc(label(u))}</strong><button data-action="remove" data-unit="${esc(u.id)}" aria-label="${esc(label(u))} entfernen" ${locked()?'disabled':''}>×</button></div>${c.hosts?`<label class="select-label" for="host-${esc(u.id)}">Plattform</label><select id="host-${esc(u.id)}" data-assign="${esc(u.id)}" data-field="parentId" ${locked()?'disabled':''}>${c.optionalHost?'<option value="">Landgestützt</option>':''}${freeHosts(units,u.type,u.id).map(p=>unitOption(p,u.parentId)).join('')}</select>`:''}${c.support?`<label class="select-label" for="support-${esc(u.id)}">Eigene Logistik</label><select id="support-${esc(u.id)}" data-assign="${esc(u.id)}" data-field="supportId" ${locked()?'disabled':''}>${freeSupports(units,u.type,u.id).map(p=>unitOption(p,u.supportId)).join('')}</select>`:''}${children.map(p=>`<button class="attached" data-action="select" data-type="${p.type}">↳ ${esc(label(p))}</button>`).join('')}</div>`;}
function bindInputs(){
 $('#search').addEventListener('input',e=>{query=e.target.value;renderCatalog();});$('#category').addEventListener('change',e=>{category=e.target.value;renderCatalog();});
 $('#group-name').addEventListener('focus',()=>{if(!locked()){history.push(copy(state.draft));if(history.length>40)history.shift();}});$('#group-name').addEventListener('input',e=>{if(locked())return;state.draft.name=e.target.value;save();});
 document.querySelectorAll('[data-rationale]').forEach(el=>{el.addEventListener('focus',()=>{if(!locked()){history.push(copy(state.draft));if(history.length>40)history.shift();}});el.addEventListener('input',e=>{if(locked())return;state.draft.rationale[e.target.dataset.rationale]=e.target.value;save();});el.addEventListener('change',()=>{const complete=QUESTIONS.filter(([k])=>state.draft.rationale[k].trim()).length;const badge=document.querySelector('[data-tab="rationale"] span');if(badge)badge.textContent=complete+'/4';});});
 const drop=$('#dropzone');drop.addEventListener('dragover',e=>{if(locked())return;e.preventDefault();drop.classList.add('drag-over');});drop.addEventListener('dragleave',e=>{if(!drop.contains(e.relatedTarget))drop.classList.remove('drag-over');});drop.addEventListener('drop',e=>{e.preventDefault();drop.classList.remove('drag-over');if(locked())return;const type=e.dataTransfer.getData('text/flottenatelier');if(BY_ID[type])act(()=>add(type));});
}
function add(type,options){const next=addUnit(state,type,options);selected=type;tab='fleet';commit(next);const u=state.draft.units.at(-1);notice(BY_ID[type].name+' hinzugefügt'+(u.parentId?' · '+label(state.draft.units.find(p=>p.id===u.parentId)):'')+'.');}
function decrease(type){const units=state.draft.units.filter(u=>u.type===type).reverse();let lastError;for(const u of units){try{const next=removeUnit(state,u.id);commit(next);return;}catch(e){lastError=e;}}if(lastError)throw lastError;}
function dialog(title,body,footer=''){const m=$('#modal');m.innerHTML=`<div class="modal-head"><div><span class="eyebrow">FLOTTENATELIER</span><h2>${title}</h2></div><button data-action="close" aria-label="Dialog schließen">×</button></div><div class="modal-body">${body}</div>${footer?`<div class="modal-foot">${footer}</div>`:''}`;if(!m.open)m.showModal();}
function summary(){const d=current(),t=totals(d.units),errors=locked()?[]:submissionErrors(d);dialog(locked()?'Eure abgegebene Flotte':'Bereit für die Diskussion?',`<div class="summary-intro"><h3>${esc(d.name||'Gruppe ohne Namen')}</h3><p>${d.iteration===1?'Erstentwurf':'Überarbeitung '+(d.iteration-1)} · ${d.units.length} Bausteine</p></div><div class="summary-totals">${Object.keys(LIMITS).map((k,i)=>`<div><b>${t[k]} / ${LIMITS[k]}</b><span>${['Aufbau','Betrieb','Personal'][i]}</span></div>`).join('')}</div><table class="summary-table"><thead><tr><th>Baustein</th><th>Anzahl</th><th>A / B / P</th></tr></thead><tbody>${CATALOG.filter(c=>count(c.id)).map(c=>`<tr><td>${esc(c.name)}</td><td>${count(c.id)}</td><td>${c.cost.build*count(c.id)} / ${c.cost.operation*count(c.id)} / ${c.cost.personnel*count(c.id)}</td></tr>`).join('')}</tbody></table>${d.units.filter(u=>u.parentId||u.supportId).length?`<h3>Zuordnungen</h3><ul>${d.units.filter(u=>u.parentId||u.supportId).map(u=>`<li>${esc(label(u))}: ${[u.parentId,u.supportId].filter(Boolean).map(id=>esc(label(d.units.find(x=>x.id===id)))).join(' · ')}</li>`).join('')}</ul>`:''}${QUESTIONS.map(([key,text])=>`<h3>${text}</h3><p class="answer">${esc(d.rationale[key]||'Noch nicht begründet.')}</p>`).join('')}${errors.length?`<div class="form-errors"><strong>Vor der Abgabe noch ergänzen</strong><ul>${errors.map(e=>`<li>${esc(e)}</li>`).join('')}</ul></div>`:'<p class="summary-note">Die Abgabe sichert diesen Stand für eure gemeinsame Diskussion. Sie ist keine fachliche Bewertung.</p>'}`,`<button data-action="print">Druckansicht / PDF</button>${locked()?'':`<button data-action="finish" class="primary" ${errors.length?'disabled':''}>Entwurf verbindlich abgeben →</button>`}`);}
function help(){dialog('So plant ihr eure Marine',`<p class="lead">Die bestehende Flotte existiert nicht. Welche Marine würdet ihr für euren Auftrag aufbauen?</p><ol class="help-steps"><li><b>Auswählen.</b> Lest Beiträge und Grenzen der Karten. Fügt Bausteine per Plus oder Ziehen hinzu.</li><li><b>Abwägen.</b> Aufbau, Betrieb und Personal sind getrennte Ressourcen. Überziehen ist im Entwurf erlaubt, bei Abgabe müssen alle Grenzen eingehalten sein.</li><li><b>Verbinden.</b> Einige Karten benötigen Strukturen oder eine freie Plattform. Im Detailbereich könnt ihr Pakete zuordnen und umordnen.</li><li><b>Begründen.</b> Haltet Prioritäten, Bausteine, Verzichte und Annahmen fest. Gebt euren Entwurf anschließend ab.</li><li><b>Diskutieren.</b> Vergleicht eure Entscheidungen mit den Experten. Erst danach beginnt ihr bei Bedarf eine Überarbeitung.</li></ol><h3>Was die Punkte bedeuten</h3><p>Aufbaukapital ist einmaliger Aufwand, Betrieb die jährliche Belastung und Personal die dauerhafte Bindung. Die Spielpunkte sind fiktiv. Eine grundlegende Landorganisation gilt als vorhanden.</p><p>Führungsnetz und Marinefliegerbasis reichen jeweils einmal für den Spielumfang. Pro Plattform ist höchstens ein Paket je zulässigem Typ möglich. Fluggeräte können, sofern ihre Karte keinen Träger verlangt, landgestützt bleiben.</p><h3>Eine Übung, keine Bewertung</h3><p>Es gibt keine Gesamtnote, keine Fähigkeitsampel und keine Musterlösung. Bauzeiten, Industrie und gewachsene Strukturen werden in der Diskussion ergänzt.</p><h3>Zeit im Seminar</h3><table class="summary-table"><tr><th>Phase</th><th>60 / 90 / 120 Min.</th></tr><tr><td>Auftrag</td><td>8 / 10 / 12</td></tr><tr><td>Regeln</td><td>5 / 8 / 8</td></tr><tr><td>Entwurf</td><td>20 / 30 / 35</td></tr><tr><td>Begründung</td><td>5 / 7 / 10</td></tr><tr><td>Diskussion</td><td>22 / 35 / 35</td></tr><tr><td>Optionale Überarbeitung</td><td>– / – / 20</td></tr></table><p>Ein Gerät je Gruppe. Eure Daten werden auf diesem Gerät gespeichert. Exportiert sie für einen Wechsel oder eine zusätzliche Sicherung.</p>`);}
function files(){dialog('Euren Entwurf sichern',`<p>Ein Export enthält den aktuellen Entwurf und alle gesicherten Abgaben. Eine importierte Datei ersetzt den lokalen Stand.</p><div class="file-actions"><button class="primary" data-action="export">Entwurf exportieren ↓</button><button data-action="import">Datei importieren ↑</button><button data-action="versions">Gespeicherte Abgaben ansehen</button><button data-action="reset" class="danger-text">Neue Gruppe beginnen</button></div>`);}
function versions(){dialog('Gesicherte Abgaben',state.submissions.length?`<p>Diese Stände bleiben auch bei einer Überarbeitung erhalten.</p><div class="version-list">${state.submissions.map((s,i)=>`<button data-action="view-version" data-index="${i}"><span><b>${i===0?'Erstabgabe':'Überarbeitung '+i}</b><small>${esc(s.name)} · ${new Date(s.submittedAt).toLocaleString('de-DE')}</small></span><span>→</span></button>`).join('')}</div>`:'<p>Es gibt noch keine Abgabe. Schließt euren Entwurf ab, um den ersten Stand zu sichern.</p>');}
function exportFile(){const blob=new Blob([JSON.stringify(state,null,2)],{type:'application/json'}),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download='Flottenatelier-'+(state.draft.name||'Gruppe').replace(/[^\p{L}\p{N}_-]/gu,'-')+'.json';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);notice('Entwurf und Abgaben exportiert.');}
function printSummary(){document.body.classList.add('printing');window.print();document.body.classList.remove('printing');}
document.addEventListener('dragstart',e=>{const c=e.target.closest('[data-type][draggable="true"]');if(c){e.dataTransfer.setData('text/flottenatelier',c.dataset.type);e.dataTransfer.effectAllowed='copy';}});
document.addEventListener('click',e=>{const b=e.target.closest('[data-action]');if(!b||b.disabled)return;act(()=>{switch(b.dataset.action){
 case 'select':selected=b.dataset.type;renderCatalog();renderDetails();break;
 case 'quickadd':add(b.dataset.type);break;
 case 'detailadd':add(b.dataset.type,{parentId:$('#add-host')?.value||null,supportId:$('#add-support')?.value||null});break;
 case 'decrease':decrease(b.dataset.type);break;
 case 'remove':commit(removeUnit(state,b.dataset.unit));break;
 case 'undo':if(!locked()&&history.length){state.draft=history.pop();save();render();notice('Letzte Änderung zurückgenommen.');}break;
 case 'tab':tab=b.dataset.tab;render();break;
 case 'help':help();break;case 'files':files();break;case 'close':$('#modal').close();break;case 'summary':summary();break;
 case 'finish':commit(submit(state),false);history=[];$('#modal').close();render();notice('Eure Abgabe ist gesichert. Jetzt beginnt die gemeinsame Diskussion.');break;
 case 'revise':commit(revise(state),false);history=[];tab='fleet';render();notice('Überarbeitung begonnen. Die Erstabgabe bleibt erhalten.');break;
 case 'versions':versions();break;
 case 'view-version':snapshot=Number(b.dataset.index);$('#modal').close();render();break;
 case 'current':snapshot=null;render();break;
 case 'export':exportFile();break;
 case 'import':$('#import-file').click();break;
 case 'reset':dialog('Neue Gruppe beginnen?',`<p>Der lokale Entwurf und seine Abgaben werden entfernt. Exportiert sie vorher, wenn ihr sie behalten möchtet.</p>`,`<button data-action="export">Vorher exportieren</button><button class="danger" data-action="confirm-reset">Lokalen Stand entfernen</button>`);break;
 case 'confirm-reset':state=fresh();history=[];snapshot=null;tab='fleet';save();$('#modal').close();render();break;
 case 'print':printSummary();break;
 case 'confirm-import':if(pendingImport){state=pendingImport;pendingImport=null;history=[];snapshot=null;tab='fleet';save();$('#modal').close();render();notice('Datei erfolgreich geladen.');}break;
 }});});
let pendingImport=null;
document.addEventListener('change',e=>{if(!e.target.matches('[data-assign]'))return;try{const u=state.draft.units.find(u=>u.id===e.target.dataset.assign);commit(assignUnit(state,u.id,e.target.dataset.field==='parentId'?e.target.value:u.parentId,e.target.dataset.field==='supportId'?e.target.value:u.supportId));}catch(err){notice(err.message,true);renderDetails();}});
$('#import-file').addEventListener('change',async e=>{const file=e.target.files[0];e.target.value='';if(!file)return;try{if(file.size>2_000_000)throw new Error('Die Datei ist zu groß (maximal 2 MB).');pendingImport=parseDocument(JSON.parse(await file.text()));dialog('Datei übernehmen?',`<p><strong>${esc(pendingImport.draft.name||'Gruppe ohne Namen')}</strong> · ${pendingImport.draft.units.length} Bausteine · ${pendingImport.submissions.length} Abgaben</p><p>Der aktuelle lokale Stand wird ersetzt. Die Datei wurde auf gültige Karten, Zuordnungen und Abgaben geprüft.</p>`,`<button data-action="export">Aktuellen Stand exportieren</button><button class="primary" data-action="confirm-import">Datei übernehmen</button>`);}catch(err){pendingImport=null;notice('Import abgelehnt: '+err.message,true);}});
$('#modal').addEventListener('click',e=>{if(e.target===$('#modal')){const r=e.target.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)e.target.close();}});
window.addEventListener('storage',e=>{if(e.key===KEY)notice('Der Entwurf wurde in einem anderen Browser-Tab geändert. Exportiert euren Stand vor dem Neuladen.',true);});
render();
if(document.modelContext?.registerTool){const lifecycle=new AbortController();window.addEventListener('pagehide',()=>lifecycle.abort(),{once:true});
 const register=tool=>{try{Promise.resolve(document.modelContext.registerTool(tool,{signal:lifecycle.signal})).catch(()=>{});}catch{}};
 register({name:'read_fleet',description:'Liest die angezeigte Flotte, Ressourcen und verfügbaren Karten ohne fachliche Bewertung.',inputSchema:{type:'object',properties:{},additionalProperties:false},annotations:{readOnlyHint:true},execute:()=>({draft:copy(current()),resources:totals(current().units),limits:LIMITS,catalog:CATALOG.map(c=>({id:c.id,name:c.name,cost:c.cost,blocked:availability(current().units,c.id)}))})});
 register({name:'add_fleet_unit',description:'Fügt genau eine Karte zum aktuellen bearbeitbaren Entwurf hinzu. Erforderliche freie Zuordnungen werden gewählt und angezeigt.',inputSchema:{type:'object',properties:{type:{type:'string',enum:CATALOG.map(c=>c.id)}},required:['type'],additionalProperties:false},annotations:{readOnlyHint:false},execute:input=>{if(!input||typeof input.type!=='string'||!BY_ID[input.type]||Object.keys(input).some(k=>k!=='type'))throw new Error('Ungültige Karte.');if(locked())throw new Error('Die angezeigte Abgabe ist schreibgeschützt.');add(input.type);return {added:copy(state.draft.units.at(-1)),resources:totals(state.draft.units)};}});
}
